20	const cacheNamespaceStorage = new AsyncLocalStorage<{ namespace: string }>();
21	
22	let enabled = getEnvBool('PROMPTFOO_CACHE_ENABLED', true);
23	
24	const cacheType =
25	  getEnvString('PROMPTFOO_CACHE_TYPE') || (getEnvString('NODE_ENV') === 'test' ? 'memory' : 'disk');
26	
27	/** Default cache TTL: 14 days in seconds */
28	const DEFAULT_CACHE_TTL_SECONDS = 60 * 60 * 24 * 14;
29	
30	/**
31	 * Get the cache TTL in milliseconds.
32	 * Reads from PROMPTFOO_CACHE_TTL environment variable (in seconds) or uses default.
33	 */
34	function getCacheTtlMs(): number {
35	  return getEnvInt('PROMPTFOO_CACHE_TTL', DEFAULT_CACHE_TTL_SECONDS) * 1000;
36	}
