92	function getNamespacedCache(namespace: string) {
93	  const cachedNamespaceInstance = namespacedCacheInstances.get(namespace);
94	  if (cachedNamespaceInstance) {
95	    return cachedNamespaceInstance;
96	  }
97	
98	  const cache = getCacheInstance();
99	  const namespacedCache = {
100	    ...cache,
101	    get: (key: string) => cache.get(getScopedCacheKey(key, namespace)),
102	    set: (key: string, value: unknown, ttl?: number) =>
103	      cache.set(getScopedCacheKey(key, namespace), value, ttl),
104	    del: (key: string) => cache.del(getScopedCacheKey(key, namespace)),
105	    mget: <T>(keys: string[]) =>
106	      cache.mget<T>(keys.map((key) => getScopedCacheKey(key, namespace))),
107	    mset: async <T>(list: Array<{ key: string; value: T; ttl?: number }>) => {
108	      const scopedList = list.map(({ key, value, ttl }) => ({
109	        key: getScopedCacheKey(key, namespace),
110	        value,
111	        ttl,
112	      }));
113	      const savedList = await cache.mset<T>(scopedList);
114	      return (savedList ?? scopedList).map(({ key, value, ttl }) => ({
115	        key: getUnscopedCacheKey(key, namespace),
116	        value,
117	        ttl,
118	      }));
119	    },
120	    mdel: (keys: string[]) => cache.mdel(keys.map((key) => getScopedCacheKey(key, namespace))),
121	    ttl: (key: string) => cache.ttl(getScopedCacheKey(key, namespace)),
122	    clear: () => clearNamespacedCache(cache, namespace),
123	    wrap: (...args: Parameters<Cache['wrap']>) =>
124	      cache.wrap(
125	        getScopedCacheKey(args[0] as string, namespace),
126	        ...(args.slice(1) as Parameters<Cache['wrap']> extends [string, ...infer Rest]
127	          ? Rest
128	          : never),
129	      ),
130	  } as Cache;
131	
132	  namespacedCacheInstances.set(namespace, namespacedCache);
133	  return namespacedCache;
134	}
135	
136	function getCurrentCacheNamespace() {
137	  return cacheNamespaceStorage.getStore()?.namespace;
138	}
139	
140	function getScopedCacheKey(cacheKey: string, namespace = getCurrentCacheNamespace()) {
141	  return namespace ? `${namespace}:${cacheKey}` : cacheKey;
142	}
143	
144	function getUnscopedCacheKey(cacheKey: string, namespace: string) {
145	  const namespacePrefix = `${namespace}:`;
146	  return cacheKey.startsWith(namespacePrefix) ? cacheKey.slice(namespacePrefix.length) : cacheKey;
147	}
148	
149	async function clearNamespacedCache(cache: Cache, namespace: string) {
150	  const namespacePrefix = `${namespace}:`;
151	
152	  for (const store of cache.stores) {
153	    if (!store.iterator) {
154	      throw new Error(
155	        `[Cache] Cannot clear namespace ${namespace} because a cache store does not support key iteration.`,
156	      );
157	    }
158	
159	    const keysToDelete: string[] = [];
160	    for await (const [key] of store.iterator(undefined)) {
161	      if (typeof key === 'string' && key.startsWith(namespacePrefix)) {
162	        keysToDelete.push(key);
163	      }
164	    }
165	
166	    if (keysToDelete.length === 0) {
167	      continue;
168	    }
169	
170	    try {
171	      if (store.deleteMany) {
172	        await store.deleteMany(keysToDelete);
173	      } else {
174	        await Promise.all(keysToDelete.map((key) => store.delete(key)));
175	      }
176	    } catch (err) {
177	      throw new Error(
178	        `[Cache] Failed to clear ${keysToDelete.length} keys for namespace "${namespace}": ${(err as Error).message}`,
179	      );
180	    }
181	  }
182	
183	  return true;
184	}
