186	export function withCacheNamespace<T>(namespace: string | undefined, fn: () => Promise<T>) {
187	  if (!namespace) {
188	    return fn();
189	  }
190	
191	  const parentNamespace = getCurrentCacheNamespace();
192	  if (parentNamespace === namespace) {
193	    return fn();
194	  }
195	
196	  const scopedNamespace = parentNamespace ? `${parentNamespace}:${namespace}` : namespace;
197	  return cacheNamespaceStorage.run({ namespace: scopedNamespace }, fn);
198	}
