110	  const cacheConfig = {
111	    endpoint: config.endpoint,
112	    apiVersion: config.apiVersion,
113	    headersHash:
114	      config.headers && Object.keys(config.headers).length > 0
115	        ? crypto
116	            .createHash('sha256')
117	            .update(
118	              JSON.stringify(
119	                Object.keys(config.headers)
120	                  .sort()
121	                  .map((k) => [k, config.headers![k]]),
122	              ),
123	            )
124	            .digest('hex')
125	            .slice(0, 16)
126	        : undefined,
127	    blocklistNames: config.blocklistNames || [],
128	    haltOnBlocklistHit: config.haltOnBlocklistHit ?? false,
129	    passthrough: config.passthrough || {},
130	  };
131	
132	  return `azure-moderation:${modelName}:${JSON.stringify(cacheConfig)}:${JSON.stringify(content)}`;
133	}
