168	
169	function getGatewayCacheConfig(config: VercelAiConfig, env?: EnvOverrides) {
170	  const headers = config.headers
171	    ? Object.fromEntries(
172	        Object.entries(config.headers)
173	          .map(([key, value]) => [key.toLowerCase(), fingerprintGatewayIdentity(value)] as const)
174	          .sort(([left], [right]) => left.localeCompare(right)),
175	      )
176	    : undefined;
177	  const apiKey = resolveApiKey(config, env);
178	  const baseUrl = resolveBaseUrl(config, env);
179	
180	  return {
181	    apiKeyFingerprint: apiKey ? fingerprintGatewayIdentity(apiKey) : undefined,
182	    baseUrlFingerprint: baseUrl === undefined ? undefined : fingerprintGatewayIdentity(baseUrl),
183	    headers,
184	  };
185	}
