190	function createTimeoutController(timeoutMs: number): {
191	  signal: AbortSignal;
192	  cleanup: () => void;
193	} {
194	  const controller = new AbortController();
195	  const timeoutId = setTimeout(() => controller.abort(), timeoutMs);
196	  return {
197	    signal: controller.signal,
198	    cleanup: () => clearTimeout(timeoutId),
199	  };
