/**
 * Builds a cache key that never embeds sensitive values (prompt/body, API key, or
 * API base URL) in raw form. Each component is hashed independently with SHA-256 so
 * that keys are stable across process restarts (no random per-session seed) while
 * still isolating cache entries by API key and API base URL.
 */
function buildMistralCacheKey(
  kind: 'chat' | 'embedding',
  modelName: string,
  requestBody: unknown,
  apiKey: string,
  apiUrl: string,
): string {
  const bodyHash = sha256(JSON.stringify(requestBody));
  const apiKeyHash = sha256(apiKey);
  const apiUrlHash = sha256(apiUrl);
  return `mistral:${kind}:${modelName}:${bodyHash}:${apiKeyHash}:${apiUrlHash}`;
}

